import{_ as e,o as a,c as r,ah as s}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Import students","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/secretariat/import-eleves.md","filePath":"src/en/guide/secretariat/import-eleves.md"}'),o={name:"en/guide/secretariat/import-eleves.md"};function n(i,t,l,h,d,m){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="import-students" tabindex="-1">Import students <a class="header-anchor" href="#import-students" aria-label="Permalink to &quot;Import students&quot;">​</a></h1><p>The <strong>Import students</strong> page, in the <strong>Students &amp; admissions</strong> space, brings over a list of students and their parents from an Excel file, instead of entering them one by one. It is mostly for moving a school to ERA or for a large start-of-year enrolment. A link on the <strong>Students</strong> page leads to it too.</p><p>It is open to the administration and the secretariat. The administration fills the classes of every site; the secretariat, those of <strong>its own site</strong> (the one on its employee profile).</p><h2 id="the-steps" tabindex="-1">The steps <a class="header-anchor" href="#the-steps" aria-label="Permalink to &quot;The steps&quot;">​</a></h2><ol><li><strong>Download the Excel file.</strong> Its first sheet is the list to fill in; the second gives the classes of the current year you can use, with their places left, and the words each column accepts.</li><li><strong>Fill it in</strong>, one row per student.</li><li><strong>Check the file</strong>: nothing is saved, the page lists the rows to fix, or tells what the import would do (students created, already present, enrolments, parents linked).</li><li><strong>Import.</strong></li></ol><h2 id="the-columns" tabindex="-1">The columns <a class="header-anchor" href="#the-columns" aria-label="Permalink to &quot;The columns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Good to know</th></tr></thead><tbody><tr><td>Last name, First name</td><td>Required.</td></tr><tr><td>Sex</td><td>Male or Female. Optional.</td></tr><tr><td>Date of birth</td><td><strong>Required</strong>, as day/month/year (25/03/2010). It tells two namesakes apart and lets a file be imported again without duplicates.</td></tr><tr><td>Place of birth</td><td>Optional.</td></tr><tr><td>Registration number</td><td>Only when the school uses registration numbers. It must be unique.</td></tr><tr><td>Site, Class</td><td>Optional. The class is the one of the current year, written as in ERA. The site only matters when two sites have a class of the same name. With no class, the student is created without an enrolment.</td></tr><tr><td>Parent 1 and Parent 2</td><td>Name, relationship (Father, Mother, Legal guardian or Other), phone, e-mail. A parent needs at least a name.</td></tr></tbody></table><p>Columns are recognised by their <strong>header</strong>: don&#39;t rename them, but you can move them or add others, which are ignored.</p><h2 id="what-the-import-does" tabindex="-1">What the import does <a class="header-anchor" href="#what-the-import-does" aria-label="Permalink to &quot;What the import does&quot;">​</a></h2><ul><li><strong>All or nothing.</strong> The whole file is checked: an unreadable date, an unknown or full class, a duplicate in the file, an invalid e-mail… and nothing is imported. Each row to fix is listed (the first thirty).</li><li><strong>Students already in ERA</strong> (same last name, first name and date of birth) are neither changed nor created again. They are only enrolled in the class of their row if they have no enrolment this year. Their parents are left alone.</li><li><strong>A full class is refused</strong>, counting the students of the file. To go over a capacity, enrol the student by hand and give the reason.</li><li><strong>Parents</strong> are found by e-mail address, which links brothers and sisters to the same account. The first parent of a row is the main contact.</li><li><strong>With no e-mail</strong>, the parent gets a placeholder address, never used to write to them. Two rows share a parent without e-mail only if the name <strong>and</strong> the phone are the same; otherwise each student has their own parent. Fill in the addresses afterwards from the <a href="/era-guide/en/guide/secretariat/parents.html">Parents</a> page.</li><li><strong>No e-mail is sent.</strong> Invitations go out afterwards, from the Parents page.</li></ul>',10)])])}const p=e(o,[["render",n]]);export{u as __pageData,p as default};
